1066:void cache_stats::get_sub_stats(struct cache_sub_stats &css) const {
1067:  ///
1068:  /// Overwrites "css" with the appropriate statistics from this cache.
1069:  ///
1070:  struct cache_sub_stats t_css;
1071:  t_css.clear();
1072:
1073:  for (auto iter = m_stats.begin(); iter != m_stats.end(); ++iter) {
1074:    unsigned long long streamID = iter->first;
1075:    for (unsigned type = 0; type < NUM_MEM_ACCESS_TYPE; ++type) {
1076:      for (unsigned status = 0; status < NUM_CACHE_REQUEST_STATUS; ++status) {
1077:        if (status == HIT || status == MISS || status == SECTOR_MISS ||
1078:            status == HIT_RESERVED)
1079:          t_css.accesses += m_stats.at(streamID)[type][status];
1080:
1081:        if (status == MISS || status == SECTOR_MISS)
1082:          t_css.misses += m_stats.at(streamID)[type][status];
1083:
1084:        if (status == HIT_RESERVED)
1085:          t_css.pending_hits += m_stats.at(streamID)[type][status];
1086:
1087:        if (status == RESERVATION_FAIL)
1088:          t_css.res_fails += m_stats.at(streamID)[type][status];
1089:      }
1090:    }
1091:  }
1092:
1093:  t_css.port_available_cycles = m_cache_port_available_cycles;
1094:  t_css.data_port_busy_cycles = m_cache_data_port_busy_cycles;
1095:  t_css.fill_port_busy_cycles = m_cache_fill_port_busy_cycles;
1096:
1097:  css = t_css;
1098:}
