158:void accel_sim_framework::cleanup(unsigned finished_kernel) {
159:  trace_kernel_info_t *k = NULL;
160:  unsigned long long finished_kernel_cuda_stream_id = -1;
161:  for (unsigned j = 0; j < kernels_info.size(); j++) {
162:    k = kernels_info.at(j);
163:    if (k->get_uid() == finished_kernel ||
164:        m_gpgpu_sim->cycle_insn_cta_max_hit() || !m_gpgpu_sim->active()) {
165:      for (unsigned int l = 0; l < busy_streams.size(); l++) {
166:        if (busy_streams.at(l) == k->get_cuda_stream_id()) {
167:          finished_kernel_cuda_stream_id = k->get_cuda_stream_id();
168:          busy_streams.erase(busy_streams.begin() + l);
169:          break;
170:        }
171:      }
172:      tracer.kernel_finalizer(k->get_trace_info());
173:      delete k->entry();
174:      delete k;
175:      kernels_info.erase(kernels_info.begin() + j);
176:      if (!m_gpgpu_sim->cycle_insn_cta_max_hit() && m_gpgpu_sim->active())
177:        break;
178:    }
179:  }
180:  if (k) {
181:    m_gpgpu_sim->print_stats(finished_kernel_cuda_stream_id);
182:    m_gpgpu_sim->perf_counters.print_counters();
183:  }
